-- ============================================================================
-- DEMO 01 (1,5 min): Estrutura Compacta (25 Tabelas) + Carga Essencial
-- Total: ~115 linhas | Nota: Functions/Procedures/Triggers/Views ficam nas
-- pastas oficiais (instale com "Rodar Core" no PG Studio ou psql -f install.sql).
-- ============================================================================

-- 1. LIMPEZA SEGURA
DROP VIEW IF EXISTS vw_escalas_jornadas_vigentes, vw_demonstrativo_adicional_noturno, vw_relatorio_inconsistencias_ponto, vw_resumo_banco_horas_colaboradores, vw_espelho_ponto_detalhado;
DROP TABLE IF EXISTS waiver_audit, absence_waiver, punch_adjustment, punch_audit, biometric_failure, timesheet, hour_bank_movement, hour_bank, daily_summary, time_punch, employee_schedule_history, work_schedule_day, work_schedule, device, employee, work_location, department, employer, job_title, waiver_type, adjustment_type, record_status, timesheet_status, punch_type, device_type;

-- 2. CREATE TABLE (25 tabelas oficiais)
CREATE TABLE device_type (device_type_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(30) NOT NULL UNIQUE);
CREATE TABLE punch_type (punch_type_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(30) NOT NULL UNIQUE);
CREATE TABLE timesheet_status (timesheet_status_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(30) NOT NULL UNIQUE);
CREATE TABLE record_status (record_status_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(30) NOT NULL UNIQUE);
CREATE TABLE adjustment_type (adjustment_type_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(30) NOT NULL UNIQUE);
CREATE TABLE waiver_type (waiver_type_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(30) NOT NULL UNIQUE);
CREATE TABLE job_title (job_title_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(60) NOT NULL UNIQUE);
CREATE TABLE employer (employer_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, cnpj char(14) NOT NULL UNIQUE, legal_name varchar(150) NOT NULL, trade_name varchar(120) NOT NULL);
CREATE TABLE department (department_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employer_id integer NOT NULL REFERENCES employer (employer_id) ON DELETE RESTRICT, name varchar(60) NOT NULL, UNIQUE (employer_id, name));
CREATE TABLE work_location (work_location_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employer_id integer NOT NULL REFERENCES employer (employer_id) ON DELETE RESTRICT, name varchar(80) NOT NULL, latitude numeric(10,8) NOT NULL, longitude numeric(11,8) NOT NULL, radius_meters integer NOT NULL, allowed_network cidr NOT NULL, UNIQUE (employer_id, work_location_id), UNIQUE (employer_id, name));
CREATE TABLE employee (employee_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employer_id integer NOT NULL, department_id integer NOT NULL REFERENCES department (department_id) ON DELETE RESTRICT, job_title_id integer NOT NULL REFERENCES job_title (job_title_id) ON DELETE RESTRICT, work_location_id integer NOT NULL, name varchar(120) NOT NULL, cpf char(11) NOT NULL UNIQUE, pis char(11) NOT NULL UNIQUE, registration_number varchar(20) NOT NULL, hire_date date NOT NULL, termination_date date, active boolean NOT NULL DEFAULT TRUE, UNIQUE (employer_id, employee_id), UNIQUE (employer_id, registration_number), FOREIGN KEY (employer_id, work_location_id) REFERENCES work_location (employer_id, work_location_id) ON DELETE RESTRICT);
CREATE TABLE device (device_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employer_id integer NOT NULL, work_location_id integer NOT NULL, device_type_id integer NOT NULL REFERENCES device_type (device_type_id) ON DELETE RESTRICT, serial_number varchar(36) NOT NULL UNIQUE, active boolean NOT NULL DEFAULT TRUE, UNIQUE (employer_id, device_id), FOREIGN KEY (employer_id, work_location_id) REFERENCES work_location (employer_id, work_location_id) ON DELETE RESTRICT);
CREATE TABLE work_schedule (work_schedule_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employer_id integer NOT NULL REFERENCES employer (employer_id) ON DELETE RESTRICT, name varchar(80) NOT NULL, daily_minutes integer NOT NULL, tolerance_minutes integer NOT NULL, UNIQUE (employer_id, name));
CREATE TABLE work_schedule_day (work_schedule_day_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, work_schedule_id integer NOT NULL REFERENCES work_schedule (work_schedule_id) ON DELETE CASCADE, weekday integer NOT NULL, day_off boolean NOT NULL, entry_time time, break_start_time time, break_end_time time, exit_time time, UNIQUE (work_schedule_id, weekday));
CREATE TABLE employee_schedule_history (employee_schedule_history_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employee_id integer NOT NULL REFERENCES employee (employee_id) ON DELETE RESTRICT, work_schedule_id integer NOT NULL REFERENCES work_schedule (work_schedule_id) ON DELETE RESTRICT, start_date date NOT NULL, end_date date);
CREATE TABLE time_punch (time_punch_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employer_id integer NOT NULL, employee_id integer NOT NULL, device_id integer NOT NULL, punch_type_id integer NOT NULL REFERENCES punch_type (punch_type_id) ON DELETE RESTRICT, sequence_number bigint NOT NULL UNIQUE, punched_at timestamp NOT NULL, latitude numeric(10,8) NOT NULL, longitude numeric(11,8) NOT NULL, ip_address inet NOT NULL, outside_perimeter boolean NOT NULL DEFAULT FALSE, FOREIGN KEY (employer_id, employee_id) REFERENCES employee (employer_id, employee_id) ON DELETE RESTRICT, FOREIGN KEY (employer_id, device_id) REFERENCES device (employer_id, device_id) ON DELETE RESTRICT);
CREATE TABLE daily_summary (daily_summary_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employee_id integer NOT NULL REFERENCES employee (employee_id) ON DELETE RESTRICT, work_date date NOT NULL, scheduled_minutes integer NOT NULL, worked_minutes integer NOT NULL, overtime_minutes integer NOT NULL, late_minutes integer NOT NULL, night_minutes integer NOT NULL, insufficient_break boolean NOT NULL, missing_clock_out boolean NOT NULL, absent boolean NOT NULL, worked_on_day_off boolean NOT NULL, UNIQUE (employee_id, work_date));
CREATE TABLE hour_bank (hour_bank_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employee_id integer NOT NULL UNIQUE REFERENCES employee (employee_id) ON DELETE RESTRICT, balance_minutes integer NOT NULL, updated_at date NOT NULL, expires_at date NOT NULL);
CREATE TABLE hour_bank_movement (hour_bank_movement_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employee_id integer NOT NULL REFERENCES employee (employee_id) ON DELETE RESTRICT, movement_date date NOT NULL, minutes integer NOT NULL, UNIQUE (employee_id, movement_date));
CREATE TABLE timesheet (timesheet_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employee_id integer NOT NULL REFERENCES employee (employee_id) ON DELETE RESTRICT, timesheet_status_id integer NOT NULL REFERENCES timesheet_status (timesheet_status_id) ON DELETE RESTRICT, start_date date NOT NULL, end_date date NOT NULL, worked_minutes integer NOT NULL, overtime_minutes integer NOT NULL, night_minutes integer NOT NULL, absence_minutes integer NOT NULL, legal_deadline date NOT NULL, closed_at timestamp, signed_at timestamp, UNIQUE (employee_id, start_date));
CREATE TABLE biometric_failure (biometric_failure_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employee_id integer NOT NULL REFERENCES employee (employee_id) ON DELETE RESTRICT, device_id integer NOT NULL REFERENCES device (device_id) ON DELETE RESTRICT, failed_at timestamp NOT NULL, reason varchar(120) NOT NULL);
CREATE TABLE punch_audit (punch_audit_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, time_punch_id integer NOT NULL REFERENCES time_punch (time_punch_id) ON DELETE RESTRICT, employee_id integer NOT NULL REFERENCES employee (employee_id) ON DELETE RESTRICT, alert_type varchar(40) NOT NULL, description varchar(255) NOT NULL);
CREATE TABLE punch_adjustment (punch_adjustment_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employee_id integer NOT NULL REFERENCES employee (employee_id) ON DELETE RESTRICT, adjustment_type_id integer NOT NULL REFERENCES adjustment_type (adjustment_type_id) ON DELETE RESTRICT, record_status_id integer NOT NULL REFERENCES record_status (record_status_id) ON DELETE RESTRICT, adjustment_date date NOT NULL, reference_at timestamp NOT NULL, reason varchar(255) NOT NULL);
CREATE TABLE absence_waiver (absence_waiver_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, employee_id integer NOT NULL REFERENCES employee (employee_id) ON DELETE RESTRICT, waiver_type_id integer NOT NULL REFERENCES waiver_type (waiver_type_id) ON DELETE RESTRICT, record_status_id integer NOT NULL REFERENCES record_status (record_status_id) ON DELETE RESTRICT, start_date date NOT NULL, end_date date NOT NULL, document varchar(255) NOT NULL, waived_minutes integer NOT NULL, responsible_user varchar(80) NOT NULL, description varchar(255) NOT NULL);
CREATE TABLE waiver_audit (waiver_audit_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, absence_waiver_id integer NOT NULL REFERENCES absence_waiver (absence_waiver_id) ON DELETE RESTRICT, employee_id integer NOT NULL REFERENCES employee (employee_id) ON DELETE RESTRICT, operation varchar(20) NOT NULL, responsible_user varchar(80) NOT NULL, audited_at timestamp NOT NULL, detail varchar(255) NOT NULL);

