INSERT INTO work_schedule_day (work_schedule_id, weekday, day_off, entry_time, break_start_time, break_end_time, exit_time)
SELECT s.work_schedule_id, w, (w IN (0,6)), CASE WHEN w IN (0,6) THEN NULL ELSE TIME '08:00' END, CASE WHEN w IN (0,6) THEN NULL ELSE TIME '12:00' END, CASE WHEN w IN (0,6) THEN NULL ELSE TIME '13:00' END, CASE WHEN w IN (0,6) THEN NULL ELSE TIME '17:00' END
  FROM work_schedule s CROSS JOIN generate_series(0,6) AS w;

