-- 4. AJUSTE DE SEQUENCES + CONFERÊNCIA
SELECT setval(pg_get_serial_sequence('employer','employer_id'), (SELECT MAX(employer_id) FROM employer)),
       setval(pg_get_serial_sequence('department','department_id'), (SELECT MAX(department_id) FROM department)),
       setval(pg_get_serial_sequence('work_location','work_location_id'), (SELECT MAX(work_location_id) FROM work_location)),
       setval(pg_get_serial_sequence('employee','employee_id'), (SELECT MAX(employee_id) FROM employee)),
       setval(pg_get_serial_sequence('device','device_id'), (SELECT MAX(device_id) FROM device)),
       setval(pg_get_serial_sequence('work_schedule','work_schedule_id'), (SELECT MAX(work_schedule_id) FROM work_schedule));

SELECT 'Tabelas criadas' AS item, COUNT(*)::text AS total FROM information_schema.tables WHERE table_schema = 'public' AND table_type = 'BASE TABLE'
UNION ALL SELECT 'Colaboradores carregados', COUNT(*)::text FROM employee
UNION ALL SELECT 'Marcações iniciais', COUNT(*)::text FROM time_punch;
